/bin/bash -lc "python - <<'PY'
import urllib.request
for u in ['https://assemblyai.com/docs/api-reference/transcripts/submit','https://www.assemblyai.com/docs/openapi.json','https://raw.githubusercontent.com/AssemblyAI/assemblyai-python-sdk/master/assemblyai/types.py']:
 try:
  s=urllib.request.urlopen(u,timeout=15).read().decode();open('/tmp/aai-'+str(len(s))+'.txt','w').write(s)
  print(u,len(s))
  for term in ['en_uk','custom_spelling','speech_models','prompt']:
   p=s.find(term); print(term,s[max(0,p-100):p+500] if p>=0 else 'absent')
 except Exception as e: print(u,str(e))
PY"

